package io.github.jesterportfolio.hearth.economy;

import java.util.*;import java.util.concurrent.*;import java.sql.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.survival.platform.JobPolicy;
import com.google.gson.Gson;import com.google.gson.reflect.TypeToken;

/** 실행 의도를 효과보다 먼저 고정한다. 재시작/불명 결과는 자동 재실행하지 않는다. */
public final class JobStore {
    public enum State {RUNNING,HOLD,SUCCEEDED,CANCELLED}
    public record Job(UUID id,String kind,String target,Map<String,String> arguments,long tick,boolean scheduled,State state,long revision,String message){public Job{arguments=Map.copyOf(arguments);if(id==null||!kind.matches("[a-z][a-z0-9_]{0,40}")||!target.matches("[a-z][a-z0-9_]{0,40}")||arguments.size()>32||arguments.entrySet().stream().anyMatch(e->!e.getKey().matches("[a-z][a-z0-9_]{0,40}")||e.getValue().length()>256)||tick<0||revision<0||message.length()>160)throw new IllegalArgumentException("JOB_DATA");}}
    public record Schedule(String target,long interval,long next,long revision){}
    public record Snapshot(List<Schedule> schedules,List<Job> jobs){public Snapshot{schedules=List.copyOf(schedules);jobs=List.copyOf(jobs);}public Optional<Job> active(){return jobs.stream().filter(j->j.state==State.RUNNING||j.state==State.HOLD).findFirst();}}
    public record Reservation(Job job,boolean replay){}
    private static final Gson JSON=new Gson();
    private final PostgresProgressStore db;private final EconomyStore economy;private final UUID realm;
    public JobStore(PostgresProgressStore db,EconomyStore economy,UUID realm){this.db=db;this.economy=economy;this.realm=realm;}
    @FunctionalInterface private interface Work<T>{T run(Connection c)throws Exception;}
    private <T>CompletionStage<T> tx(String operation,ServerProgressAccess.Context ctx,Work<T> work){return db.module(operation,c->{c.setAutoCommit(false);try{if(!ctx.storyRunId().equals(realm))throw fail("JOB_SCOPE");economy.housingLock(c,ctx);var result=work.run(c);c.commit();return result;}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}});}
    private ServerProgressAccess.Context system(){return economy.context(realm,new UUID(0,0));}
    private static StorageFailure fail(String code){return new StorageFailure("platform_jobs",code);}
    private static String arguments(Map<String,String> values){String s=JSON.toJson(new TreeMap<>(values));if(s.length()>4096)throw new IllegalArgumentException("JOB_ARGUMENTS");return s;}
    private Job row(ResultSet r)throws Exception{return new Job(r.getObject("request_id",UUID.class),r.getString("kind"),r.getString("target"),JSON.fromJson(r.getString("arguments"),new TypeToken<Map<String,String>>(){}.getType()),r.getLong("started_tick"),r.getBoolean("scheduled"),State.valueOf(r.getString("state")),r.getLong("revision"),r.getString("message"));}
    private Snapshot snapshot(Connection c)throws Exception{var schedules=new ArrayList<Schedule>();try(var s=c.prepareStatement("SELECT target,interval_ticks,next_tick,revision FROM hearth_economy.platform_schedule WHERE realm_id=? ORDER BY target")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next())schedules.add(new Schedule(r.getString(1),r.getLong(2),r.getLong(3),r.getLong(4)));}}var jobs=new ArrayList<Job>();try(var s=c.prepareStatement("SELECT * FROM hearth_economy.platform_job WHERE realm_id=? AND NOT archived ORDER BY CASE WHEN state IN ('RUNNING','HOLD') THEN 0 ELSE 1 END,created_at DESC,request_id LIMIT 128")){s.setObject(1,realm);try(var r=s.executeQuery()){while(r.next())jobs.add(row(r));}}return new Snapshot(schedules,jobs);}
    public CompletionStage<Snapshot> snapshot(){return tx("job_snapshot",system(),this::snapshot);}
    public CompletionStage<Optional<Job>> inspect(UUID id){return tx("job_inspect",system(),c->{try(var s=c.prepareStatement("SELECT * FROM hearth_economy.platform_job WHERE realm_id=? AND request_id=?")){s.setObject(1,realm);s.setObject(2,id);try(var r=s.executeQuery()){return r.next()?Optional.of(row(r)):Optional.empty();}}});}
    public CompletionStage<Snapshot> recover(){return tx("job_recover",system(),c->{try(var s=c.prepareStatement("UPDATE hearth_economy.platform_job SET state='HOLD',message='RESTART_REVIEW',revision=revision+1 WHERE realm_id=? AND state='RUNNING'")){s.setObject(1,realm);s.executeUpdate();}return snapshot(c);});}
    public CompletionStage<Snapshot> configure(Map<String,Long> intervals,long now){if(!intervals.keySet().equals(JobPolicy.ROLES)||intervals.values().stream().anyMatch(n->n<0||n>100_000_000L)||now<0)throw new IllegalArgumentException("JOB_CONFIG");return tx("job_configure",system(),c->{var old=snapshot(c);for(var e:new TreeMap<>(intervals).entrySet()){var before=old.schedules.stream().filter(s->s.target.equals(e.getKey())).findFirst();if(before.isPresent()&&before.get().interval==e.getValue())continue;if(old.active().isPresent())throw fail("JOB_CONFIG_BUSY");long next=e.getValue()==0?now:JobPolicy.next(now,e.getValue());try(var s=c.prepareStatement("INSERT INTO hearth_economy.platform_schedule VALUES(?,?,?,?,0) ON CONFLICT(realm_id,target) DO UPDATE SET interval_ticks=EXCLUDED.interval_ticks,next_tick=EXCLUDED.next_tick,revision=hearth_economy.platform_schedule.revision+1")){s.setObject(1,realm);s.setString(2,e.getKey());s.setLong(3,e.getValue());s.setLong(4,next);s.executeUpdate();}}return snapshot(c);});}
    public CompletionStage<Reservation> reserve(ServerProgressAccess.Context ctx,UUID id,String kind,String target,Map<String,String> args,long now,Schedule schedule){var candidate=new Job(id,kind,target,args,now,schedule!=null,State.RUNNING,0,"");String encoded=arguments(candidate.arguments);return tx("job_reserve",ctx,c->{try(var s=c.prepareStatement("SELECT * FROM hearth_economy.platform_job WHERE realm_id=? AND request_id=?")){s.setObject(1,realm);s.setObject(2,id);try(var r=s.executeQuery()){if(r.next()){var old=row(r);if(!old.kind.equals(kind)||!old.target.equals(target)||!old.arguments.equals(candidate.arguments)||old.tick!=now||old.scheduled!=(schedule!=null))throw fail("JOB_REQUEST_CONFLICT");return new Reservation(old,true);}}}var state=snapshot(c);if(state.active().isPresent())throw fail("JOB_BUSY");if(schedule!=null){if(!kind.equals("resource_reset")||!target.equals(schedule.target))throw fail("JOB_SCHEDULE_SCOPE");var actual=state.schedules.stream().filter(s->s.target.equals(target)).findFirst().orElseThrow();if(!actual.equals(schedule)||actual.interval<=0||now<actual.next)throw fail("JOB_SCHEDULE_STALE");}try(var s=c.prepareStatement("SELECT count(*) FROM hearth_economy.platform_job WHERE realm_id=? AND NOT archived")){s.setObject(1,realm);try(var r=s.executeQuery()){r.next();if(r.getLong(1)>=4096)throw fail("JOB_HISTORY_CAPACITY");}}try(var s=c.prepareStatement("INSERT INTO hearth_economy.platform_job(realm_id,request_id,version,kind,target,arguments,started_tick,scheduled,state,revision,message) VALUES(?,?,1,?,?,?,?,?,'RUNNING',0,'')")){s.setObject(1,realm);s.setObject(2,id);s.setString(3,kind);s.setString(4,target);s.setString(5,encoded);s.setLong(6,now);s.setBoolean(7,schedule!=null);s.executeUpdate();}return new Reservation(candidate,false);});}
    public CompletionStage<Job> finish(Job original,State state,String message,long now){if(!Set.of(State.HOLD,State.SUCCEEDED,State.CANCELLED).contains(state)||message.length()>160||now<original.tick)throw new IllegalArgumentException("JOB_FINISH");return tx("job_finish",system(),c->{try(var q=c.prepareStatement("SELECT * FROM hearth_economy.platform_job WHERE realm_id=? AND request_id=?")){q.setObject(1,realm);q.setObject(2,original.id);try(var r=q.executeQuery()){if(!r.next()||!row(r).equals(original))throw fail("JOB_CAS");}}Job done;try(var s=c.prepareStatement("UPDATE hearth_economy.platform_job SET state=?,revision=revision+1,message=? WHERE realm_id=? AND request_id=? AND revision=? AND NOT archived AND state IN ('RUNNING','HOLD') RETURNING *")){s.setString(1,state.name());s.setString(2,message);s.setObject(3,realm);s.setObject(4,original.id);s.setLong(5,original.revision);try(var r=s.executeQuery()){if(!r.next())throw fail("JOB_CAS");done=row(r);}}if(original.kind.equals("resource_reset")&&state!=State.HOLD){try(var s=c.prepareStatement("UPDATE hearth_economy.platform_schedule SET next_tick=?+interval_ticks,revision=revision+1 WHERE realm_id=? AND target=? AND interval_ticks>0")){s.setLong(1,now);s.setObject(2,realm);s.setString(3,original.target);s.executeUpdate();}}return done;});}
}
